mods=['pulsar-broker','pulsar-broker-common','pulsar-client','pulsar-client-api','pulsar-common','pulsar-metadata','managed-ledger']
files=[]
for m in mods:
    root=os.path.join(m,'src','main','java')
    for d,_,fs in os.walk(root):
        for f in fs:
            if f.endswith('.java') and f not in('package-info.java','module-info.java'):
                files.append(os.path.join(d,f))
def strip(s):
    s=re.sub(r'/\*.*?\*/','',s,flags=re.S)
    s=re.sub(r'"(?:\\.|[^"\\\n])*"','""',s)
    s=re.sub(r'//[^\n]*','',s)
    return s
types={} # fqn->file
info={}
decl=re.compile(r'^(?:public\s+|abstract\s+|final\s+|sealed\s+|static\s+)*(?:class|interface|enum|record|@interface)\s+(\w+)',re.M)
for f in files:
    s=strip(open(f,encoding='utf8').read())
    pk=re.search(r'^\s*package\s+([\w.]+);',s,re.M)
    if not pk or not pk.group(1).startswith('org.apache.pulsar'): continue
    pk=pk.group(1)
    # top-level types: depth 0
    depth=0;tops=[];i=0
    for line in s.split('\n'):
        if depth==0:
            m=decl.match(line.strip())
            if m: tops.append(m.group(1))
        depth+=line.count('{')-line.count('}')
    info[f]=(pk,tops,s)
    for t in tops: types[pk+'.'+t]=f
bypkg=collections.defaultdict(list)
for fq in types: bypkg[fq.rsplit('.',1)[0]].append(fq)
cnt=collections.defaultdict(set)
for f,(pk,tops,s) in info.items():
    me=set(pk+'.'+t for t in tops)
    body=re.sub(r'^\s*(package|import)[^;]*;','',s,flags=re.M)
    toks=set(re.findall(r'\b[A-Za-z_]\w*\b',body))
    refs=set()
    imps=re.findall(r'^\s*import\s+(static\s+)?([\w.]+)(\.\*)?;',s,re.M)
    simple_imported={}
    for st,name,wc in imps:
        if wc:
            if st:
                # static wildcard: class name
                if name in types: refs.add(name)
            else:
                for fq in bypkg.get(name,[]):
                    if fq.rsplit('.',1)[1] in toks: refs.add(fq)
                # nested wildcard import of Outer.*
                if name in types: refs.add(name)
        else:
            parts=name.split('.')
            for k in range(len(parts),0,-1):
                c='.'.join(parts[:k])
                if c in types:
                    # check used (imports are used presumably)
                    refs.add(c);break
    for fq in bypkg.get(pk,[]):
        if fq.rsplit('.',1)[1] in toks: refs.add(fq)
    for fq in re.findall(r'\borg\.apache\.pulsar(?:\.\w+)+',body):
        parts=fq.split('.')
        for k in range(len(parts),0,-1):
            c='.'.join(parts[:k])
            if c in types: refs.add(c);break
    for r in refs:
        if r not in me:
            cnt[r].add(f)
for fq,c in sorted(cnt.items(),key=lambda x:-len(x[1]))[:15]: print(fq,len(c))
